create extension if not exists pgcrypto;
create table if not exists public.users(id uuid primary key default gen_random_uuid(),discord_id text unique not null,username text not null,avatar text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.servers(id uuid primary key default gen_random_uuid(),guild_id text unique not null,name text not null,icon text,owner_discord_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.server_settings(id uuid primary key default gen_random_uuid(),guild_id text unique not null references public.servers(guild_id) on delete cascade,prefix text default '!',language text default 'en',enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.moderation_settings(id uuid primary key default gen_random_uuid(),guild_id text unique not null references public.servers(guild_id) on delete cascade,enabled boolean not null default true,anti_spam boolean not null default false,anti_link boolean not null default false,mod_log_channel text,moderator_roles jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.welcome_settings(id uuid primary key default gen_random_uuid(),guild_id text unique not null references public.servers(guild_id) on delete cascade,enabled boolean not null default false,channel_id text,message text default 'Welcome {user} to {server}!',mention boolean not null default true,embed boolean not null default true,image_url text,auto_role_id text,goodbye_enabled boolean not null default false,goodbye_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ticket_settings(id uuid primary key default gen_random_uuid(),guild_id text unique not null references public.servers(guild_id) on delete cascade,enabled boolean not null default false,panel_channel_id text,category_id text,support_role_id text,log_channel_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.command_settings(id uuid primary key default gen_random_uuid(),guild_id text unique not null references public.servers(guild_id) on delete cascade,commands jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.logging_settings(id uuid primary key default gen_random_uuid(),guild_id text unique not null references public.servers(guild_id) on delete cascade,enabled boolean not null default false,channels jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),guild_id text not null,actor_discord_id text,action text not null,target_id text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists audit_logs_guild_created_idx on public.audit_logs(guild_id,created_at desc);
alter table public.users enable row level security; alter table public.servers enable row level security; alter table public.server_settings enable row level security; alter table public.moderation_settings enable row level security; alter table public.welcome_settings enable row level security; alter table public.ticket_settings enable row level security; alter table public.command_settings enable row level security; alter table public.logging_settings enable row level security; alter table public.audit_logs enable row level security;
